PRAGMA foreign_keys = ON;
CREATE TABLE prj24_customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE);
CREATE TABLE prj24_tickets (ticket_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES prj24_customers(customer_id), subject TEXT NOT NULL, priority INTEGER NOT NULL CHECK (priority BETWEEN 1 AND 5), status TEXT NOT NULL);
INSERT INTO prj24_customers VALUES (1, 'Asha', 'asha@example.test');
INSERT INTO prj24_tickets VALUES (101, 1, 'Cannot sign in', 5, 'open');
SELECT t.ticket_id, c.customer_name, t.subject FROM prj24_tickets t JOIN prj24_customers c ON c.customer_id=t.customer_id;

